import{_ as s,o as i,c as a,an as t}from"./chunks/framework.C1Zpw0WN.js";const u=JSON.parse('{"title":"Unified Transport-Binary Generation","description":"","frontmatter":{},"headers":[],"relativePath":"preprocessing/unified_binary_generation.md","filePath":"preprocessing/unified_binary_generation.md","lastUpdated":null}'),n={name:"preprocessing/unified_binary_generation.md"};function o(l,e,r,p,d,c){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="Unified-Transport-Binary-Generation" tabindex="-1">Unified Transport-Binary Generation <a class="header-anchor" href="#Unified-Transport-Binary-Generation" aria-label="Permalink to &quot;Unified Transport-Binary Generation {#Unified-Transport-Binary-Generation}&quot;">​</a></h1><p>This note is the production contract for every preprocessor that writes transport binaries. The source may be ERA5 spectral fields, native GEOS/GCHP fields, or a future met reader; the target may be lat-lon, reduced Gaussian, or cubed sphere. Those choices change only the dispatched methods. They do not change the lifecycle.</p><h2 id="One-Lifecycle" tabindex="-1">One Lifecycle <a class="header-anchor" href="#One-Lifecycle" aria-label="Permalink to &quot;One Lifecycle {#One-Lifecycle}&quot;">​</a></h2><p>Every binary-producing path must follow this sequence:</p><ol><li><p>Build a typed source reader and a typed target geometry.</p></li><li><p>Allocate a target workspace for one day of windows.</p></li><li><p>Ingest each source met window into target air mass and flux buffers.</p></li><li><p>Choose the integer <code>steps_per_window[win]</code> from the shared <code>SubstepSchedulePolicy</code>.</p></li><li><p>Rescale stored per-substep flux amounts when the selected step count changes.</p></li><li><p>Balance the horizontal and vertical mass closure against the explicit window endpoint using that selected step count.</p></li><li><p>Verify the topology contract: replay continuity plus per-substep positivity.</p></li><li><p>Write the payload and patch the header schedule before close.</p></li><li><p>Load-time readers reject any binary whose header schedule, Poisson scale, and payload semantics disagree.</p></li></ol><p>The generic lifecycle is <code>run_unified_preprocessor_day!</code>. A topology supplies only the methods that are physically topology-specific:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">driver_windows_per_day</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(reader, context)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">driver_ingest_window!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(workspace, reader, win, context)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">driver_drain_ready_windows!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(workspace, contract, win, context)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">driver_flush_final_windows!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(workspace, reader, contract, context)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">driver_before_close_writer!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(workspace, reader, contract, writer, context)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">driver_after_write_window!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(workspace, reader, ready, context)</span></span></code></pre></div><p>If a new source or topology cannot implement one of these methods, the missing method should fail at dispatch or construction time. It should not silently use a parallel script with different header semantics.</p><h2 id="Substep-Schedule-Semantics" tabindex="-1">Substep Schedule Semantics <a class="header-anchor" href="#Substep-Schedule-Semantics" aria-label="Permalink to &quot;Substep Schedule Semantics {#Substep-Schedule-Semantics}&quot;">​</a></h2><p><code>format_version = 4</code> stores fluxes according to the explicit <code>flux_kind</code> contract:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>flux_kind = &quot;substep_mass_amount&quot;</span></span>
<span class="line"><span>m_next - m_cur = 2 * steps_per_window[win] * div(stored_half_sweep_fluxes)</span></span></code></pre></div><p>Therefore changing <code>steps_per_window[win]</code> requires changing the payload:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>new_flux = old_flux * old_steps / new_steps</span></span>
<span class="line"><span>cm       = recomputed from (m_next - m_cur) / (2 * new_steps)</span></span></code></pre></div><p>Header-only schedule edits are invalid. Format v4 permits full-window mass amounts only for cubed-sphere products, where the runtime divides by the stored schedule; LL and reduced-Gaussian products require substep mass amounts.</p><h2 id="Shared-Policy" tabindex="-1">Shared Policy <a class="header-anchor" href="#Shared-Policy" aria-label="Permalink to &quot;Shared Policy {#Shared-Policy}&quot;">​</a></h2><p>All paths use <code>SubstepSchedulePolicy</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SubstepSchedulePolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    adaptive_substeps </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    substep_cfl_target </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.95</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    min_steps_per_window </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    max_steps_per_window </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The selected step count is the smallest integer that brings the measured positivity ratio under <code>substep_cfl_target</code>, clamped to the configured bounds. The schedule is not restricted to powers of two.</p><p>The default TOML behavior is adaptive CFL scheduling. A fixed schedule is an explicit opt-out:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">numerics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">substep_schedule = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fixed&quot;</span></span></code></pre></div><p>Fixed schedules still run the final positivity contract. If it fails, the staged binary is removed unless the diagnostic escape hatch is explicitly enabled.</p><h2 id="Topology-Responsibilities" tabindex="-1">Topology Responsibilities <a class="header-anchor" href="#Topology-Responsibilities" aria-label="Permalink to &quot;Topology Responsibilities {#Topology-Responsibilities}&quot;">​</a></h2><p>Lat-lon stores directional structured fluxes. It chooses a per-window schedule, rescales <code>am</code> and <code>bm</code>, recomputes <code>cm</code>, and rewrites the deferred header before the first payload byte is committed.</p><p>Reduced Gaussian stores face-indexed horizontal fluxes. It chooses a per-window schedule in the sliding-buffer drain step, rescales <code>hflux</code>, recomputes <code>cm</code>, and patches the streaming header before close.</p><p>Cubed sphere stores per-panel directional fluxes. Native GEOS and ERA5-spectral CS both choose a per-window schedule, rescale <code>am</code> and <code>bm</code>, recompute <code>cm</code>, and write <code>runtime_substep_contract = &quot;binary_schedule&quot;</code> so the runtime honors the baked schedule instead of re-piloting CS CFL.</p><h2 id="Contract-Failure-Modes" tabindex="-1">Contract Failure Modes <a class="header-anchor" href="#Contract-Failure-Modes" aria-label="Permalink to &quot;Contract Failure Modes {#Contract-Failure-Modes}&quot;">​</a></h2><p>These are hard errors:</p><ul><li><p>Missing or obsolete <code>format_version</code>.</p></li><li><p>Missing <code>steps_per_window_by_window</code>.</p></li><li><p><code>steps_per_window != maximum(steps_per_window_by_window)</code>.</p></li><li><p><code>poisson_balance_target_scale_by_window[win] != 1 / (2 * steps_per_window[win])</code>.</p></li><li><p>Header declares a binary schedule that the runtime cannot honor.</p></li><li><p>Replay continuity failure after balancing.</p></li><li><p>Per-substep positivity failure after adaptive refinement reaches its ceiling.</p></li></ul><p>These rules make old binaries obsolete and make partial regeneration failures obvious at preprocessing time, not during a transport campaign.</p>`,29)])])}const k=s(n,[["render",o]]);export{u as __pageData,k as default};
